CPU = "Processor time used during the sample, as a percentage of all logical processors combined (100% means the whole machine). Calculated from Windows process CPU-time counters."
WORKING_SET = "Working set: process pages currently resident in RAM, including shared pages. Read from Windows process memory counters; formatted in powers of 1024. Shared pages can be counted in more than one process."
PRIVATE_SET = "Private working set: RAM pages belonging only to this process, read from Windows process counters and formatted in powers of 1024. Unlike Private bytes, this excludes private committed pages currently outside RAM."
IO = "Process read/write transfer rate calculated from changes in Windows I/O byte counters, in bytes per second (scaled by 1024). These counters can include cached and device I/O; this is not physical-disk bandwidth alone."

HEADERS = {
    "Name": "The name reported by the row's Windows data source; a name alone does not establish identity or trust.",
    "Process": "Executable name reported by the process reader; different processes can have the same name.",
    "PID": "Process identifier assigned by Windows. It is a number, not a permanent identity: Windows can reuse it after a process exits.",
    "CPU": CPU, "CPU%": CPU, "CPU %": CPU,
    "RAM": WORKING_SET, "RSS": WORKING_SET, "Memory": PRIVATE_SET,
    "Memory MB": "Resident working-set memory from psutil, divided by 1024 squared (MiB, displayed as MB). Includes shared pages; it is not Private bytes.",
    "Private bytes": "Committed virtual memory allocated exclusively to this process, in bytes. It can be in RAM or backed by the page file; it is not the private working set.",
    "Disk": IO, "Disk R": IO + " This column shows reads.", "Disk W": IO + " This column shows writes.",
    "Net In": "Bytes received per second attributed to this process by the reader. Unavailable readings are not evidence that the process is offline.",
    "Net Out": "Bytes sent per second attributed to this process by the reader. Unavailable readings are not evidence that the process is offline.",
    "GPU%": "Graphics-processor utilization from the process GPU counter reader, in percent. GPU engines handle different workloads; this is not CPU use or graphics-memory occupancy.",
    "GPU engine": "Windows GPU engine associated with the reading, such as 3D, copy or video decode. Engines perform different work; an idle 3D engine does not mean the whole GPU is idle.",
    "User": "Windows account owning the process, read from its access token when permitted. A blank value can mean access was refused.",
    "Path": "Executable or mapped-file path reported by the row's reader. Missing or refused paths do not establish that a file has been deleted.",
    "Full path": "Full path of the loaded executable module, read from the process module enumeration.",
    "Threads": "Number of execution threads in the process's Windows snapshot. Threads can exist while waiting and consume no CPU.",
    "Handles": "Number of open Windows object references held by the process, from the process snapshot. These include more than files and are not a count of open windows.",
    "CPU time": "Cumulative user-mode plus kernel-mode processor time, from Windows process counters. Multiple threads can accumulate more CPU time than elapsed wall-clock time.",
    "Started": "Process creation time reported by Windows, displayed in local time. This is not when the executable was installed.",
    "Elevated": "Whether the Windows process token is elevated. This differs from simply belonging to the Administrators group; blank means the token could not be read.",
    "Integrity": "Windows mandatory integrity level read from the process token, such as Low, Medium, High or System. It restricts access between trust levels; it is not an antivirus verdict.",
    "Arch": "Process architecture reported by Windows, such as 32-bit or 64-bit. This describes the program, not necessarily the operating system.",
    "Command line": "Command and arguments used to start the process, read when Windows permits. Arguments can contain sensitive information.",
    "Publisher": "Publisher/company text from the file or installation metadata. This self-reported text is not proof of a valid digital signature.",
    "Company": "Company name from the module's version resource. This is file metadata, not a verified signer identity.",
    "Description": "Description text supplied by the file or Windows provider. Treat it as metadata, not an independent identification.",
    "Version": "Version string supplied by the file or installation registration; it has not been checked against the latest vendor release.",
    "TID": "Thread identifier assigned by Windows; it can be reused after the thread exits.",
    "User Time": "Cumulative seconds this thread spent executing application code in user mode, read through psutil from Windows.",
    "System Time": "Cumulative seconds this thread spent executing Windows kernel-mode code, read through psutil from Windows.",
    "Type": "Object, registration or session type reported by the reader for this row.",
    "Handle": "Hexadecimal handle value in the owning process's handle table. The value is local to that process and can be reused.",
    "Object address": "Kernel object address reported by native Windows handle enumeration, in hexadecimal. It may be hidden by Windows; it is not a file offset.",
    "Access": "Granted-access bit mask reported for this handle, in hexadecimal. The meaning of each bit depends on the object type.",
    "Base address": "Virtual address where the module is loaded in this process, in hexadecimal; it is not an address on disk.",
    "Size": "Size reported by this row's reader, formatted in bytes or multiples of 1024; see the pane description for what is measured.",
    "Signed": "Authenticode signature verdict from the app's verifier. Yes means a valid signature; No means unsigned; unavailable differs from invalid. A signature alone does not guarantee harmless behavior.",
    "Permissions": "Memory-region access permissions returned by the memory-map provider, when available. Blank means this field was not supplied, not that all access is denied.",
    "Private": "Private memory for the region, formatted in powers of 1024, only if supplied by the memory-map provider. The current view substitutes 0 when this field is absent; that is not a measured zero.",
    "Protocol": "Transport protocol from the Windows endpoint list: TCP for connections, UDP for datagram endpoints.",
    "Proto": "Transport protocol from psutil's Windows endpoint list: TCP or UDP.",
    "Local Address": "Local network address bound to this endpoint, from Windows. A wildcard such as 0.0.0.0 or :: means all local interfaces of that address family.",
    "Remote Address": "Peer address reported by Windows. Listening sockets and unconnected UDP endpoints may have no remote address.",
    "Local Port": "Local transport port number, from Windows; it identifies an endpoint, not necessarily a unique program.",
    "Remote Port": "Peer transport port number reported by Windows, if connected.",
    "Local address": "Local IP address and port from psutil's Windows endpoint list. A wildcard address means all local interfaces of that address family.",
    "Remote address": "Peer IP address and port reported by Windows; listeners and unconnected UDP endpoints may have none.",
    "State": "Connection or session state reported by Windows. TCP states describe a connection's lifecycle; UDP has no TCP connection state.",
    "Time": "Time the app recorded this activity event, rather than a Windows Event Log timestamp.",
    "Event": "Type of process activity detected by this app; this is not the full Windows Event Log.",
    "Detail": "Additional explanation supplied by this row's collector or test; missing details are not independently inferred.",
    "Privilege": "Windows token privilege name, identifying a specific right such as debugging another process.",
    "Status": "State reported by this pane's data source. An unavailable read is different from an explicit negative result.",
    "Group": "Group membership in the process access token, as reported by Windows.",
    "SID": "Security identifier: Windows' stable identifier for an account or group. A SID can remain even if its friendly name cannot be resolved.",
    "Flags": "Windows token attribute flags for this entry; enabled, disabled and deny-only have different effects on access checks.",
    "Mitigation policy": "Process exploit-protection policy queried from Windows. A refused read does not mean the policy is disabled.",
    "Protection": "Windows protected-process status returned by the mitigation reader. Protection can prevent inspection even when elevated.",
    "DEP": "Data Execution Prevention: Windows policy preventing execution from non-executable memory pages, when the process policy can be read.",
    "ASLR": "Address Space Layout Randomization: process policy randomizing memory locations to hinder exploitation. Read from Windows mitigation policies.",
    "CFG": "Control Flow Guard: process policy restricting indirect-call targets. Read from Windows mitigation policies, not a malware scan.",
    "Display Name": "Friendly service name reported by Win32_Service; the internal Name is used for service-control operations.",
    "Start Type": "Service startup configuration from Windows: automatic, manual or disabled, with extra trigger/delayed details where available. Manual services can still start on demand.",
    "Impact": "App-derived service assessment from the service-view rules, not a Windows measurement of boot time or CPU cost.",
    "Log on as": "Account configured to run the service, reported by Win32_Service; this is not necessarily the signed-in user.",
    "Installed": "Installation date supplied by the app's uninstall registration. It can be missing or reflect an update rather than the original install.",
    "Drive": "Mounted drive path reported by Windows via psutil; different letters need not be different physical disks.",
    "File system": "Filesystem type reported by the drive reader, such as NTFS; this is not a disk-health test.",
    "Free": "Available drive capacity reported by psutil.disk_usage, formatted in powers of 1024.",
    "Used": "Used drive capacity from psutil.disk_usage, formatted in powers of 1024; includes more than the folders this user can scan.",
    "Used %": "Used capacity as a percentage of the drive's reported total capacity, from psutil.disk_usage.",
    "Folder": "Folder path examined by the app's folder-size scanner; access-denied folders can make the scan incomplete.",
    "Share of drive": "Scanned folder size divided by total drive capacity, shown as a percentage; it is not a share of only the visible folders.",
    "Session": "Windows session number from process/session enumeration. Different sign-ins or Remote Desktop sessions can have separate numbers.",
    "Client": "Client name reported by the Windows Terminal Services session reader, if available.",
    "Core": "Core identifier supplied by this pane's CPU topology or energy-meter reader. Multiple logical processors can belong to one physical core.",
    "NUMA": "Non-Uniform Memory Access node number from Windows CPU topology. Processors in a node share a local memory-access domain.",
    "Nominal": "Base frequency in MHz returned by CallNtPowerInformation. It does not follow live boost frequency.",
    "Effective": "Estimated effective MHz: nominal MHz multiplied by the Windows % Processor Performance counter. It can exceed nominal during boost; it is not a direct clock-probe measurement.",
    "Windows limit": "Maximum MHz currently allowed by Windows, from CallNtPowerInformation. A limit is not the current clock or proof of thermal throttling.",
    "Test": "Benchmark performed by this app; results depend on other activity and the chosen drive.",
    "Result": "Measured benchmark value with its test-specific unit, such as throughput or elapsed time. Compare like tests and conditions.",
    "vs last run": "Change from this app's previous stored result for the same benchmark. Differences can reflect background activity as well as hardware performance.",
    "Power": "Core power from Windows Energy Meter counters, converted from milliwatts to watts (W). This is CPU energy-meter data, not power measured at the wall socket.",
    "Est. power": "Estimated process watts: its CPU-time share multiplied by measured package power. This is not a per-process energy-meter reading and does not attribute idle draw.",
    "Command / path": "Command registered to launch at sign-in, read from Windows startup locations. Displaying it does not execute it.",
    "Source": "Windows registry or folder location from which this startup entry was read; this explains where it is registered.",
    "Details": "Additional startup registration information reported by the reader, rather than an inferred purpose for the program.",
    "Hardware": "Hardware component associated with the Windows reading, when supplied by the source.",
    "Now": "Current value and unit supplied by this thermal/clock reader. Missing sensors are not replaced with estimated temperatures.",
    "Reading": "Name of the temperature or clock-limit signal being reported; a frequency limit alone does not establish a thermal cause.",
    "Sensor": "Thermal sensor or zone name published by the Windows provider. An ACPI zone need not be the CPU package sensor.",
    "Temperature": "Temperature in degrees Celsius from a Windows-exposed thermal sensor; not every machine publishes one.",
    "Processes": "Number of currently running processes included in this app-history group, not a lifetime launch count.",
    "Running since": "Earliest creation time among currently running processes in this group, read from Windows. Closed processes are not retained here.",
    "Item": "Hardware or operating-system property reported by the system-information reader.",
    "Value": "Value returned by this row's provider, with units where supplied. Unavailable data is not an independently verified negative result.",
    "Variable": "Environment variable name read from the selected process. Its value may contain sensitive information.",
    "By CPU": "Processes ranked by CPU use at the selected recorded sample; values come from the trace, not the current live process list.",
    "By GPU": "Processes ranked by available GPU use at the selected recorded sample; missing GPU readings are not zero use.",
    "By disk": "Processes ranked by I/O byte rate at the selected recorded sample, not total bytes over the recording.",
    "By memory": "Processes ranked by private working-set bytes at the selected recorded sample; this is resident private RAM, not Private bytes.",
    "Machine": "Machine name stored in the recording metadata; opening a trace does not connect to that machine.",
    "Duration": "Elapsed time covered by the saved trace, from its sample timestamps.",
    "Samples": "Number of samples stored in the trace; unavailable individual counters may still appear as gaps.",
    "Modified": "Last-modified time of the trace file as reported by the filesystem.",
}

